//! The app-owned shadcn Neutral theme for gpuicn.
//!
//! Source: shadcn/ui 4.19.0 at
//! `1773ecfeeb4a04366978d353e69b5c7ded78dcb2`, Nova style.

use std::time::Duration;

use gpui::{
    App, BoxShadow, Corners, Div, ElementId, Global, ParentElement as _, Pixels, Rgba,
    SharedString, Styled, Window, black, px,
};

gpui::actions!(
    gpuicn,
    [
        /// Move to the next keyboard tab stop.
        FocusNext,
        /// Move to the previous keyboard tab stop.
        FocusPrevious
    ]
);

struct Initialized;
impl Global for Initialized {}

/// Installs component actions, keyboard traversal and the default theme once.
/// Call this from application startup for both copied source and crate usage.
pub fn init(cx: &mut App) {
    if cx.has_global::<Initialized>() {
        return;
    }
    cx.set_global(Initialized);
    if !cx.has_global::<UiTheme>() {
        UiTheme::set(cx, UiTheme::neutral_light());
    }
    cx.bind_keys([
        gpui::KeyBinding::new("tab", FocusNext, None),
        gpui::KeyBinding::new("shift-tab", FocusPrevious, None),
    ]);
    cx.on_action(|_: &FocusNext, cx| advance_focus(false, cx));
    cx.on_action(|_: &FocusPrevious, cx| advance_focus(true, cx));
    // Later scoped bindings take precedence over window-wide defaults.
    gpui_base::init(cx);
    base_gpui::init(cx);
    #[cfg(target_family = "wasm")]
    {
        // WASM has no macOS target_os, so Base GPUI only registers Control
        // shortcuts. Accept Command as well for previews on macOS browsers.
        use base_gpui::primitives::input::{
            INPUT_KEY_CONTEXT, InputCopy, InputCut, InputEnd, InputHome, InputPaste, InputSelectAll,
        };
        use gpui::KeyBinding;
        cx.bind_keys([
            KeyBinding::new("cmd-a", InputSelectAll, Some(INPUT_KEY_CONTEXT)),
            KeyBinding::new("cmd-c", InputCopy, Some(INPUT_KEY_CONTEXT)),
            KeyBinding::new("cmd-v", InputPaste, Some(INPUT_KEY_CONTEXT)),
            KeyBinding::new("cmd-x", InputCut, Some(INPUT_KEY_CONTEXT)),
            KeyBinding::new("cmd-left", InputHome, Some(INPUT_KEY_CONTEXT)),
            KeyBinding::new("cmd-right", InputEnd, Some(INPUT_KEY_CONTEXT)),
        ]);
    }
}

fn advance_focus(reverse: bool, cx: &mut App) {
    let Some(handle) = cx.active_window() else {
        return;
    };
    // Action dispatch still holds the window borrow until this callback returns.
    cx.defer(move |cx| {
        let _ = handle.update(cx, |_, window, cx| {
            if reverse {
                window.focus_prev(cx);
            } else {
                window.focus_next(cx);
            }
        });
    });
}

/// The active color mode.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum ThemeMode {
    /// The Neutral light palette.
    Light,
    /// The Neutral dark palette.
    Dark,
}

/// Semantic colors consumed by installed components.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct UiColors {
    /// App background.
    pub background: Rgba,
    /// Default foreground.
    pub foreground: Rgba,
    /// Card background.
    pub card: Rgba,
    /// Card foreground.
    pub card_foreground: Rgba,
    /// Popover background.
    pub popover: Rgba,
    /// Popover foreground.
    pub popover_foreground: Rgba,
    /// Primary control background.
    pub primary: Rgba,
    /// Primary control foreground.
    pub primary_foreground: Rgba,
    /// Secondary control background.
    pub secondary: Rgba,
    /// Secondary control foreground.
    pub secondary_foreground: Rgba,
    /// Muted background.
    pub muted: Rgba,
    /// Muted foreground.
    pub muted_foreground: Rgba,
    /// Accent background.
    pub accent: Rgba,
    /// Accent foreground.
    pub accent_foreground: Rgba,
    /// Destructive action color.
    pub destructive: Rgba,
    /// Default border.
    pub border: Rgba,
    /// Input border.
    pub input: Rgba,
    /// Focus ring.
    pub ring: Rgba,
    /// First chart color.
    pub chart_1: Rgba,
    /// Second chart color.
    pub chart_2: Rgba,
    /// Third chart color.
    pub chart_3: Rgba,
    /// Fourth chart color.
    pub chart_4: Rgba,
    /// Fifth chart color.
    pub chart_5: Rgba,
    /// Sidebar background.
    pub sidebar: Rgba,
    /// Sidebar foreground.
    pub sidebar_foreground: Rgba,
    /// Sidebar primary background.
    pub sidebar_primary: Rgba,
    /// Sidebar primary foreground.
    pub sidebar_primary_foreground: Rgba,
    /// Sidebar accent background.
    pub sidebar_accent: Rgba,
    /// Sidebar accent foreground.
    pub sidebar_accent_foreground: Rgba,
    /// Sidebar border.
    pub sidebar_border: Rgba,
    /// Sidebar focus ring.
    pub sidebar_ring: Rgba,
    /// Scrim behind modal surfaces.
    pub overlay: Rgba,
}

/// Theme font family names. Applications own font loading.
#[derive(Clone, Debug, PartialEq)]
pub struct UiFonts {
    /// Default body family.
    pub body: SharedString,
    /// Default heading family.
    pub heading: SharedString,
    /// Default monospace family.
    pub mono: SharedString,
}

/// Corner radii derived from shadcn's 10px base radius.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct UiRadius {
    /// Backward-compatible alias for [`Self::lg`].
    pub base: Pixels,
    /// Six pixels (`radius * 0.6`).
    pub sm: Pixels,
    /// Eight pixels (`radius * 0.8`).
    pub md: Pixels,
    /// Ten pixels (the configured base radius).
    pub lg: Pixels,
    /// Fourteen pixels (`radius * 1.4`).
    pub xl: Pixels,
    /// Eighteen pixels (`radius * 1.8`).
    pub two_xl: Pixels,
    /// Twenty-two pixels (`radius * 2.2`).
    pub three_xl: Pixels,
    /// Twenty-six pixels (`radius * 2.6`).
    pub four_xl: Pixels,
}

impl UiRadius {
    /// Derives the complete Nova radius scale from one nonnegative base radius.
    pub fn new(base: Pixels) -> Self {
        assert!(f32::from(base).is_finite() && base >= px(0.));
        Self {
            base,
            sm: base * 0.6,
            md: base * 0.8,
            lg: base,
            xl: base * 1.4,
            two_xl: base * 1.8,
            three_xl: base * 2.2,
            four_xl: base * 2.6,
        }
    }
}

/// Shared UI transition durations. Honor these alongside `App::reduce_motion()`.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct UiMotion {
    /// Thumb and small-state transitions (150ms by default).
    pub fast: Duration,
    /// Panel/layout transitions (200ms by default).
    pub normal: Duration,
    /// Application preference; true removes movement without removing state feedback.
    pub reduced: bool,
    /// Shared easing for reversible state transitions.
    pub easing: UiEasing,
}
impl Default for UiMotion {
    fn default() -> Self {
        Self {
            fast: Duration::from_millis(150),
            normal: Duration::from_millis(200),
            reduced: false,
            easing: UiEasing::EaseInOut,
        }
    }
}

/// Curves supported by the shared native transition helper.
#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
pub enum UiEasing {
    /// Constant-speed motion, as used by shadcn sidebar layout transitions.
    Linear,
    /// Fast response followed by a smooth stop.
    EaseOut,
    /// Smooth acceleration and deceleration for changes within a layout.
    #[default]
    EaseInOut,
}
impl UiEasing {
    fn sample(self, progress: f32) -> f32 {
        match self {
            Self::Linear => progress,
            Self::EaseOut => gpui::ease_out_quint()(progress),
            Self::EaseInOut => gpui::ease_in_out(progress),
        }
    }
}

/// Returns a smoothly retargetable value for one stable, caller-named property.
/// Starts at the target on mount; rapid reversals continue from the current value.
/// Honors theme and GPUI reduced-motion settings and schedules no idle frames.
/// Use for state changes, never for pointer-drag coordinates or keyboard navigation.
/// Native layout transitions perform layout work; retain expensive child entities.
pub fn transition_value(
    id: impl Into<ElementId>,
    target: f32,
    duration: Duration,
    window: &mut Window,
    cx: &mut App,
) -> f32 {
    assert!(target.is_finite(), "transition targets must be finite");
    let motion = UiTheme::read(cx).motion;
    let duration = if motion.reduced || cx.reduce_motion() {
        Duration::ZERO
    } else {
        duration
    };
    gpui_base::motion::transition(
        id.into(),
        target,
        gpui_base::motion::Transition::new(duration)
            .ease(move |progress| motion.easing.sample(progress)),
        window,
        cx,
    )
}

/// Shared shadcn elevation tokens.
#[derive(Clone, Debug, PartialEq)]
pub struct UiShadows {
    /// Tailwind `shadow-sm`.
    pub sm: Vec<BoxShadow>,
    /// Tailwind `shadow-md`.
    pub md: Vec<BoxShadow>,
    /// Tailwind `shadow-lg`.
    pub lg: Vec<BoxShadow>,
}

/// Base spacing unit from the pinned Nova style.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct UiSpacing {
    /// Four pixels.
    pub unit: Pixels,
}

/// The application-owned theme stored in GPUI global state.
#[derive(Clone, Debug, PartialEq)]
pub struct UiTheme {
    /// Active color mode.
    pub mode: ThemeMode,
    /// Active semantic colors.
    pub colors: UiColors,
    /// Font family names.
    pub fonts: UiFonts,
    /// Base corner radius.
    pub radius: UiRadius,
    /// Base spacing unit.
    pub spacing: UiSpacing,
    /// Shared elevation and focus-ring tokens.
    pub shadows: UiShadows,
    /// Shared motion durations and reduced-motion preference.
    pub motion: UiMotion,
    /// Typography scale, independent of control density (1 by default).
    pub text_scale: f32,
}

impl Global for UiTheme {}

impl Default for UiTheme {
    fn default() -> Self {
        Self::neutral_light()
    }
}

impl UiTheme {
    /// Creates the pinned Neutral light theme.
    pub fn neutral_light() -> Self {
        Self::new(ThemeMode::Light, neutral_light_colors())
    }

    /// Creates the pinned Neutral dark theme.
    pub fn neutral_dark() -> Self {
        Self::new(ThemeMode::Dark, neutral_dark_colors())
    }

    /// Installs a theme into the application.
    pub fn set(cx: &mut App, theme: Self) {
        assert!(f32::from(theme.spacing.unit).is_finite() && theme.spacing.unit > px(0.));
        assert!(theme.text_scale.is_finite() && theme.text_scale > 0.);
        cx.set_global(theme);
        cx.refresh_windows();
    }

    /// Reads the installed theme.
    ///
    /// Panics when the application has not installed a theme.
    pub fn read(cx: &App) -> &Self {
        cx.global::<Self>()
    }

    /// Selects the pinned palette, preserving non-color tokens or initializing defaults.
    pub fn switch(cx: &mut App, mode: ThemeMode) {
        let mut theme = cx
            .try_global::<Self>()
            .cloned()
            .unwrap_or_else(Self::neutral_light);
        theme.mode = mode;
        theme.colors = match mode {
            ThemeMode::Light => neutral_light_colors(),
            ThemeMode::Dark => neutral_dark_colors(),
        };
        Self::set(cx, theme);
    }

    /// Returns a multiple of the configured spacing unit (2 means 8px by default).
    pub fn space(&self, units: f32) -> Pixels {
        self.spacing.unit * units
    }

    /// Scales typography independently of spacing; sizes use Nova's default pixels.
    pub fn text(&self, size: f32) -> Pixels {
        px(size * self.text_scale)
    }

    /// Builds shadcn's three-pixel focus ring from the active semantic ring color.
    pub fn focus_ring(&self) -> Vec<BoxShadow> {
        vec![
            BoxShadow::new(px(0.), px(0.), self.colors.ring.opacity(0.50).into())
                .spread_radius(px(3.)),
        ]
    }

    /// Builds shadcn's invalid focus ring from the active destructive color.
    pub fn destructive_focus_ring(&self) -> Vec<BoxShadow> {
        let alpha = match self.mode {
            ThemeMode::Light => 0.20,
            ThemeMode::Dark => 0.40,
        };
        vec![
            BoxShadow::new(
                px(0.),
                px(0.),
                self.colors.destructive.opacity(alpha).into(),
            )
            .spread_radius(px(3.)),
        ]
    }

    fn new(mode: ThemeMode, colors: UiColors) -> Self {
        Self {
            mode,
            colors,
            fonts: UiFonts {
                body: "Geist".into(),
                heading: "Geist".into(),
                mono: "Geist Mono".into(),
            },
            radius: UiRadius::new(px(10.)),
            motion: UiMotion::default(),
            text_scale: 1.,
            spacing: UiSpacing { unit: px(4.) },
            shadows: UiShadows {
                sm: vec![
                    BoxShadow::new(px(0.), px(1.), black().alpha(0.10)).blur_radius(px(3.)),
                    BoxShadow::new(px(0.), px(1.), black().alpha(0.10))
                        .blur_radius(px(2.))
                        .spread_radius(px(-1.)),
                ],
                md: vec![
                    BoxShadow::new(px(0.), px(4.), black().alpha(0.10))
                        .blur_radius(px(6.))
                        .spread_radius(px(-1.)),
                    BoxShadow::new(px(0.), px(2.), black().alpha(0.10))
                        .blur_radius(px(4.))
                        .spread_radius(px(-2.)),
                ],
                lg: vec![
                    BoxShadow::new(px(0.), px(10.), black().alpha(0.10))
                        .blur_radius(px(15.))
                        .spread_radius(px(-3.)),
                    BoxShadow::new(px(0.), px(4.), black().alpha(0.10))
                        .blur_radius(px(6.))
                        .spread_radius(px(-4.)),
                ],
            },
        }
    }
}

fn neutral_light_colors() -> UiColors {
    UiColors {
        background: neutral(1.0),
        foreground: neutral(0.145),
        card: neutral(1.0),
        card_foreground: neutral(0.145),
        popover: neutral(1.0),
        popover_foreground: neutral(0.145),
        primary: neutral(0.205),
        primary_foreground: neutral(0.985),
        secondary: neutral(0.97),
        secondary_foreground: neutral(0.205),
        muted: neutral(0.97),
        muted_foreground: neutral(0.556),
        accent: neutral(0.97),
        accent_foreground: neutral(0.205),
        destructive: srgb(0xdc, 0x26, 0x26),
        border: neutral(0.922),
        input: neutral(0.922),
        ring: neutral(0.708),
        chart_1: neutral(0.87),
        chart_2: neutral(0.556),
        chart_3: neutral(0.439),
        chart_4: neutral(0.371),
        chart_5: neutral(0.269),
        sidebar: neutral(0.985),
        sidebar_foreground: neutral(0.145),
        sidebar_primary: neutral(0.205),
        sidebar_primary_foreground: neutral(0.985),
        sidebar_accent: neutral(0.97),
        sidebar_accent_foreground: neutral(0.205),
        sidebar_border: neutral(0.922),
        sidebar_ring: neutral(0.708),
        overlay: black().alpha(0.10).into(),
    }
}

fn neutral_dark_colors() -> UiColors {
    UiColors {
        background: neutral(0.145),
        foreground: neutral(0.985),
        card: neutral(0.205),
        card_foreground: neutral(0.985),
        popover: neutral(0.205),
        popover_foreground: neutral(0.985),
        primary: neutral(0.922),
        primary_foreground: neutral(0.205),
        secondary: neutral(0.269),
        secondary_foreground: neutral(0.985),
        muted: neutral(0.269),
        muted_foreground: neutral(0.708),
        accent: neutral(0.269),
        accent_foreground: neutral(0.985),
        destructive: srgb(0xff, 0x64, 0x67),
        border: neutral_alpha(1.0, 0.10),
        input: neutral_alpha(1.0, 0.15),
        ring: neutral(0.556),
        chart_1: neutral(0.87),
        chart_2: neutral(0.556),
        chart_3: neutral(0.439),
        chart_4: neutral(0.371),
        chart_5: neutral(0.269),
        sidebar: neutral(0.205),
        sidebar_foreground: neutral(0.985),
        sidebar_primary: srgb(0x14, 0x47, 0xe6),
        sidebar_primary_foreground: neutral(0.985),
        sidebar_accent: neutral(0.269),
        sidebar_accent_foreground: neutral(0.985),
        sidebar_border: neutral_alpha(1.0, 0.10),
        sidebar_ring: neutral(0.556),
        overlay: black().alpha(0.10).into(),
    }
}

pub(super) fn neutral(l: f64) -> Rgba {
    neutral_alpha(l, 1.0)
}

fn neutral_alpha(l: f64, alpha: f64) -> Rgba {
    let channel = srgb_channel(l * l * l) as f32;

    Rgba {
        r: channel,
        g: channel,
        b: channel,
        a: alpha.clamp(0.0, 1.0) as f32,
    }
}

const fn srgb(red: u8, green: u8, blue: u8) -> Rgba {
    Rgba {
        r: red as f32 / 255.0,
        g: green as f32 / 255.0,
        b: blue as f32 / 255.0,
        a: 1.0,
    }
}

fn srgb_channel(channel: f64) -> f64 {
    if channel >= 0.003_130_8 {
        (1.055 * channel.powf(1.0 / 2.4) - 0.055).clamp(0.0, 1.0)
    } else {
        (12.92 * channel).clamp(0.0, 1.0)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn editor_semantics_survive_upstream_id_assignment() {
        use gpui::{Element as _, InteractiveElement as _, StatefulInteractiveElement as _};
        let input = InputSemantics(gpui::div())
            .role(gpui::Role::SpinButton)
            .aria_label("Quantity")
            .aria_value("4")
            .aria_numeric_value(4.)
            .0
            .id("upstream-editor");
        assert_eq!(input.a11y_role(), Some(gpui::Role::SpinButton));
        let mut node = gpui::accesskit::Node::new(gpui::Role::SpinButton);
        input.write_a11y_info(&mut node);
        assert_eq!(node.label(), Some("Quantity"));
        assert_eq!(node.value(), Some("4"));
        assert_eq!(node.numeric_value(), Some(4.));
    }

    #[test]
    fn converts_pinned_neutral_tokens() {
        assert_eq!(
            neutral(1.0),
            Rgba {
                r: 1.0,
                g: 1.0,
                b: 1.0,
                a: 1.0,
            }
        );
        assert_eq!(
            neutral(0.0),
            Rgba {
                r: 0.0,
                g: 0.0,
                b: 0.0,
                a: 1.0,
            }
        );

        assert_eq!(neutral_light_colors().destructive, srgb(0xdc, 0x26, 0x26));
        assert_eq!(neutral_dark_colors().destructive, srgb(0xff, 0x64, 0x67));
        assert_eq!(
            neutral_dark_colors().sidebar_primary,
            srgb(0x14, 0x47, 0xe6)
        );
    }

    #[test]
    fn preserves_pinned_alpha_tokens() {
        let dark = neutral_dark_colors();
        assert_eq!(dark.border.a, 0.10);
        assert_eq!(dark.input.a, 0.15);
        assert_eq!(dark.sidebar_border.a, 0.10);
        assert!((dark.input.opacity(0.30).a - 0.045).abs() < f32::EPSILON);
    }

    #[test]
    fn derives_the_shadcn_radius_and_shadow_scales() {
        let theme = UiTheme::neutral_light();
        assert_eq!(theme.radius.sm, px(6.));
        assert_eq!(theme.radius.md, px(8.));
        assert_eq!(theme.radius.lg, px(10.));
        assert_eq!(theme.radius.xl, px(14.));
        assert_eq!(theme.shadows.sm.len(), 2);
        assert_eq!(theme.shadows.md.len(), 2);
        assert_eq!(theme.shadows.lg.len(), 2);
        assert_eq!(theme.focus_ring()[0].spread_radius, px(3.));
    }
}

/// Adds semantics to an upstream editor's existing Div before it receives its ID.
/// Keeping the same Div preserves the editor's focus handle and event handlers.
pub(crate) struct InputSemantics(pub Div);
impl gpui::InteractiveElement for InputSemantics {
    fn interactivity(&mut self) -> &mut gpui::Interactivity {
        self.0.interactivity()
    }
}
impl gpui::StatefulInteractiveElement for InputSemantics {}
impl gpui::IntoElement for InputSemantics {
    type Element = Div;
    fn into_element(self) -> Div {
        self.0
    }
}

/// Centers the Base GPUI single-line editor independently of inherited typography.
/// The editor sizes its text and caret from the line height, so padding alone
/// cannot keep both centered across bordered and borderless controls.
pub(crate) fn input_text_layout(base: Div, text_scale: f32) -> Div {
    base.flex().items_center().line_height(px(20.) * text_scale)
}

/// Draws concentric focus corners; GPUI spread shadows retain the inner radius.
pub(crate) fn focus_outline(mut base: Div, color: Rgba, radii: Corners<Pixels>) -> Div {
    let borders = base.style().border_widths.clone();
    base.child(gpui::deferred(
        gpui::canvas(
            |_, _, _| (),
            move |bounds, _, window, _| {
                let rem = window.rem_size();
                let borders = gpui::Edges {
                    left: borders.left.unwrap_or_default().to_pixels(rem),
                    top: borders.top.unwrap_or_default().to_pixels(rem),
                    right: borders.right.unwrap_or_default().to_pixels(rem),
                    bottom: borders.bottom.unwrap_or_default().to_pixels(rem),
                };
                window.paint_quad(focus_outline_quad(bounds, color, radii, borders));
            },
        )
        .absolute()
        .inset_0(),
    ))
}

fn focus_outline_quad(
    mut bounds: gpui::Bounds<Pixels>,
    color: Rgba,
    radii: Corners<Pixels>,
    borders: gpui::Edges<Pixels>,
) -> gpui::PaintQuad {
    bounds.origin.x -= borders.left + px(3.);
    bounds.origin.y -= borders.top + px(3.);
    bounds.size.width += borders.left + borders.right + px(6.);
    bounds.size.height += borders.top + borders.bottom + px(6.);
    gpui::outline(bounds, color, Default::default())
        .corner_radii(radii.map(|r| if *r > px(0.) { *r + px(3.) } else { *r }))
        .border_widths(px(3.))
}

#[cfg(test)]
mod focus_outline_tests {
    use super::*;
    #[test]
    fn focus_outlines_follow_circle_and_segment_borders() {
        let bounds = gpui::Bounds::new(gpui::point(px(1.), px(1.)), gpui::size(px(10.), px(10.)));
        let quad = focus_outline_quad(
            bounds,
            black().into(),
            Corners::all(px(6.)),
            gpui::Edges::all(px(1.)),
        );
        assert_eq!(quad.bounds.origin, gpui::point(px(-3.), px(-3.)));
        assert_eq!(quad.bounds.size, gpui::size(px(18.), px(18.)));
        assert_eq!(quad.corner_radii, Corners::all(px(9.)));
        let quad = focus_outline_quad(
            bounds,
            black().into(),
            Corners::all(px(0.)),
            gpui::Edges {
                left: px(0.),
                ..gpui::Edges::all(px(1.))
            },
        );
        assert_eq!(quad.bounds.origin.x, px(-2.));
        assert_eq!(quad.bounds.size.width, px(17.));
        assert_eq!(quad.corner_radii, Corners::all(px(0.)));
    }
}

// Refine the actual control after default styling; no extra layout or focus node.
pub(crate) fn apply_style<T: Styled>(mut element: T, style: &gpui::StyleRefinement) -> T {
    use gpui::Refineable as _;
    element.style().refine(style);
    element
}

#[derive(gpui::IntoElement)]
pub(crate) struct DisclosureIcon {
    icon: gpui::Svg,
    open: bool,
}
pub(crate) fn disclosure_icon(icon: gpui::Svg, open: bool) -> DisclosureIcon {
    DisclosureIcon { icon, open }
}
impl gpui::RenderOnce for DisclosureIcon {
    fn render(self, window: &mut Window, cx: &mut App) -> impl gpui::IntoElement {
        let duration = UiTheme::read(cx).motion.fast;
        let value = transition_value(
            "disclosure-rotation",
            if self.open { 1. } else { 0. },
            duration,
            window,
            cx,
        );
        self.icon
            .with_transformation(gpui::Transformation::rotate(gpui::radians(
                value * std::f32::consts::PI,
            )))
    }
}

#[cfg(test)]
mod motion_tests {
    use super::*;
    use gpui::{
        AppContext as _, Context, IntoElement, Render, TestAppContext, VisualTestContext, div,
    };

    struct View {
        target: f32,
        sampled: f32,
    }
    impl Render for View {
        fn render(&mut self, window: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
            self.sampled = transition_value(
                "test-motion",
                self.target,
                Duration::from_millis(200),
                window,
                cx,
            );
            div()
        }
    }

    #[gpui::test]
    fn theme_reduced_motion_snaps_an_active_upstream_transition(cx: &mut TestAppContext) {
        cx.update(init);
        let window = cx.add_window(|_, _| View {
            target: 0.,
            sampled: 0.,
        });
        let mut visual = VisualTestContext::from_window(window.into(), cx);
        visual.update(|window, cx| window.draw(cx).clear(cx));
        window
            .update(cx, |view, _, cx| {
                view.target = 1.;
                cx.notify();
            })
            .unwrap();
        visual.update(|window, cx| window.draw(cx).clear(cx));
        assert_eq!(
            cx.read_window(&window, |view, cx| view.read(cx).sampled)
                .unwrap(),
            0.
        );
        cx.update(|cx| {
            let mut theme = UiTheme::read(cx).clone();
            theme.motion.reduced = true;
            UiTheme::set(cx, theme);
        });
        visual.update(|window, cx| window.draw(cx).clear(cx));
        assert_eq!(
            cx.read_window(&window, |view, cx| view.read(cx).sampled)
                .unwrap(),
            1.
        );
    }
}

#![allow(missing_docs)]
//! Nova-styled native text input with IME, field registration and standard editing shortcuts.

#[path = "input_editing.rs"]
mod editing;
#[path = "input_text.rs"]
mod text;

use std::rc::Rc;

use base_gpui::primitives::input::*;
use base_gpui::{
    field::{
        FieldControlRegistration, FieldValue, current_field_context, current_field_item_disabled,
    },
    fieldset::current_fieldset_disabled,
};
use editing::Editing;
use gpui::{
    App, Div, ElementId, Entity, Global, InteractiveElement as _, IntoElement, KeyBinding,
    MouseButton, ParentElement as _, RenderOnce, Role, SharedString,
    StatefulInteractiveElement as _, Styled, Window, div, prelude::FluentBuilder as _, px,
};
use text::InputTextElement;

use super::theme::{ThemeMode, UiTheme, input_text_layout};

type ValueChange = Rc<dyn Fn(SharedString) + 'static>;
type ChangeHandler = Rc<dyn Fn(SharedString, &mut Window, &mut App) + 'static>;
type ContextHandler = Rc<dyn Fn(&SharedString, &mut Window, &mut App) + 'static>;
type FocusHandler = Rc<dyn Fn(bool, &mut Window, &mut App)>;
type StyleHandler = Rc<dyn Fn(InputStyleState, Div) -> Div + 'static>;
/// Shared wiring for editors hosted inside numeric or roving-focus controls.
#[derive(Clone, Default)]
pub(crate) struct CompositeInput {
    pub focus: Option<gpui::FocusHandle>,
    pub tab_stop: Option<bool>,
    pub select_all_on_focus: bool,
    pub register_field: bool,
    pub role: Option<Role>,
    pub on_home: Option<ChangeHandler>,
    pub on_end: Option<ChangeHandler>,
    pub on_edge_left: Option<ChangeHandler>,
    pub on_edge_right: Option<ChangeHandler>,
    pub on_focus_change: Option<FocusHandler>,
}

gpui::actions!(
    gpuicn_input,
    [
        InputUndo,
        InputRedo,
        InputWordLeft,
        InputWordRight,
        InputSelectWordLeft,
        InputSelectWordRight,
        InputSelectHome,
        InputSelectEnd,
        InputDeleteWordLeft,
        InputDeleteWordRight,
        InputDeleteToStart,
        InputDeleteToEnd
    ]
);
struct Initialized;
impl Global for Initialized {}

#[derive(IntoElement)]
pub struct Input {
    style: gpui::StyleRefinement,
    id: ElementId,
    value: Option<SharedString>,
    default_value: Option<SharedString>,
    placeholder: Option<SharedString>,
    aria_label: Option<SharedString>,
    name: Option<SharedString>,
    on_change: Option<ContextHandler>,
    on_submit: Option<ContextHandler>,
    style_with_state: Option<StyleHandler>,
    disabled: bool,
    read_only: bool,
    required: bool,
    on_value_change: Option<ValueChange>,
    on_enter: Option<ValueChange>,
    auto_focus: bool,
    focus_handle: Option<gpui::FocusHandle>,
    composite: Option<CompositeInput>,
}

impl Input {
    pub fn new(id: impl Into<ElementId>) -> Self {
        Self {
            style: gpui::StyleRefinement::default(),
            id: id.into(),
            value: None,
            default_value: None,
            placeholder: None,
            aria_label: None,
            name: None,
            on_change: None,
            on_submit: None,
            style_with_state: None,
            disabled: false,
            read_only: false,
            required: false,
            on_value_change: None,
            on_enter: None,
            auto_focus: false,
            focus_handle: None,
            composite: None,
        }
    }
    pub(crate) fn composite(mut self, composite: CompositeInput) -> Self {
        self.composite = Some(composite);
        self
    }
    pub(crate) fn id(mut self, id: impl Into<ElementId>) -> Self {
        self.id = id.into();
        self
    }
    pub fn value(mut self, value: impl Into<SharedString>) -> Self {
        self.value = Some(value.into());
        self
    }
    pub fn default_value(mut self, value: impl Into<SharedString>) -> Self {
        self.default_value = Some(value.into());
        self
    }
    pub fn placeholder(mut self, value: impl Into<SharedString>) -> Self {
        self.placeholder = Some(value.into());
        self
    }
    pub fn aria_label(mut self, value: impl Into<SharedString>) -> Self {
        self.aria_label = Some(value.into());
        self
    }
    pub fn name(mut self, name: impl Into<SharedString>) -> Self {
        self.name = Some(name.into());
        self
    }
    /// Receive edits with GPUI context; accepts `cx.listener(...)` directly.
    pub fn on_change(
        mut self,
        handler: impl Fn(&SharedString, &mut Window, &mut App) + 'static,
    ) -> Self {
        self.on_change = Some(Rc::new(handler));
        self
    }
    /// Submit the current value with GPUI context when Enter is pressed.
    pub fn on_submit(
        mut self,
        handler: impl Fn(&SharedString, &mut Window, &mut App) + 'static,
    ) -> Self {
        self.on_submit = Some(Rc::new(handler));
        self
    }
    /// Refine the default styles while retaining editing and focus behavior.
    pub fn style_with_state(
        mut self,
        style: impl Fn(InputStyleState, Div) -> Div + 'static,
    ) -> Self {
        self.style_with_state = Some(Rc::new(style));
        self
    }
    pub fn disabled(mut self, value: bool) -> Self {
        self.disabled = value;
        self
    }
    pub fn read_only(mut self, value: bool) -> Self {
        self.read_only = value;
        self
    }
    pub fn required(mut self, value: bool) -> Self {
        self.required = value;
        self
    }
    pub fn on_value_change(mut self, handler: impl Fn(SharedString) + 'static) -> Self {
        self.on_value_change = Some(Rc::new(handler));
        self
    }
    /// Focus the input when it first mounts, for example an opened task composer.
    pub fn auto_focus(mut self, value: bool) -> Self {
        self.auto_focus = value;
        self
    }
    /// Use a stable handle so another control can focus this editor.
    pub fn focus_handle(mut self, focus: gpui::FocusHandle) -> Self {
        self.focus_handle = Some(focus);
        self
    }
    /// Submit the current native editing value when Enter is pressed.
    pub fn on_enter(mut self, handler: impl Fn(SharedString) + 'static) -> Self {
        self.on_enter = Some(Rc::new(handler));
        self
    }
}

impl RenderOnce for Input {
    fn render(self, window: &mut Window, cx: &mut App) -> impl IntoElement {
        init(cx);
        let theme = UiTheme::read(cx).clone();
        let spacing = theme.spacing.unit;
        let text_scale = theme.text_scale;
        let colors = theme.colors;
        let field_context = current_field_context();
        let aria_label = self.aria_label.or_else(|| {
            field_context
                .as_ref()
                .and_then(|context| context.label_text(cx))
        });
        let field_state = field_context
            .as_ref()
            .map(|context| context.read(cx, |runtime, props| runtime.root_state(props)));
        let disabled = self.disabled
            || field_state.is_some_and(|state| state.disabled)
            || current_field_item_disabled()
            || current_fieldset_disabled();
        let valid = field_state.and_then(|state| state.valid);
        let field_context = field_context.filter(|_| {
            self.composite
                .as_ref()
                .is_none_or(|props| props.register_field)
        });
        let initial_value = self
            .value
            .clone()
            .or(self.default_value)
            .unwrap_or_default();
        let state: Entity<Editing> =
            window.use_keyed_state((self.id.clone(), "editing"), cx, |window, cx| {
                match self.focus_handle.clone().or_else(|| {
                    self.composite
                        .as_ref()
                        .and_then(|props| props.focus.clone())
                }) {
                    Some(focus) => Editing::new_with_focus_handle(initial_value, focus, window, cx),
                    None => Editing::new(initial_value, window, cx),
                }
            });
        let focus = state.read(cx).focus_handle();
        let mut registration = FieldControlRegistration::new(self.id.to_string())
            .disabled(disabled)
            .required(self.required)
            .focus_handle(focus.clone());
        if let Some(name) = self.name {
            registration = registration.name(name);
        }
        let changed_registration = registration.clone();
        let changed_field = field_context.clone();
        let changed_focus = focus.clone();
        let form_context = base_gpui::form::current_form_context();
        let change: ChangeHandler = Rc::new(move |value, window, cx| {
            // Keep form validation current even if Enter arrives before another frame.
            if let Some(context) = &changed_field {
                context.register_control(
                    changed_registration
                        .clone()
                        .value(FieldValue::Text(value.clone()))
                        .focused(changed_focus.is_focused(window)),
                    cx,
                );
            }
            if let Some(handler) = &self.on_value_change {
                handler(value.clone());
            }
            if let Some(handler) = &self.on_change {
                handler(&value, window, cx);
            }
        });
        let submit: ChangeHandler = Rc::new(move |value, window, cx| {
            if self.on_enter.is_none()
                && self.on_submit.is_none()
                && let Some(context) = &form_context
            {
                context.submit(base_gpui::form::FormSubmitReason::Action, window, cx);
                return;
            }
            if let Some(handler) = &self.on_enter {
                handler(value.clone());
            }
            if let Some(handler) = &self.on_submit {
                handler(&value, window, cx);
            }
        });
        state.update(cx, |editing, cx| {
            editing.composite = self.composite.clone().unwrap_or_default();
            editing.sync_props(
                self.value,
                disabled,
                self.read_only,
                self.required,
                Some(change),
                Some(submit),
                cx,
            )
        });
        let auto_focused: Entity<bool> =
            window.use_keyed_state((self.id.clone(), "auto-focus"), cx, |_, _| false);
        if self.auto_focus && !disabled && !*auto_focused.read(cx) {
            focus.focus(window, cx);
            *auto_focused.as_mut(cx) = true;
        }
        let style_state = state.read(cx).style_state(window, valid);
        if let Some(context) = field_context {
            context.register_control(
                registration
                    .value(FieldValue::Text(style_state.value.clone()))
                    .focused(style_state.focused),
                cx,
            );
        }
        let focus_ring = if style_state.invalid {
            theme.destructive_focus_ring()
        } else {
            theme.focus_ring()
        };
        let border = if style_state.invalid {
            colors
                .destructive
                .opacity(if theme.mode == ThemeMode::Dark {
                    0.5
                } else {
                    1.0
                })
        } else {
            colors.input
        };
        let background = match theme.mode {
            ThemeMode::Light => colors.background,
            ThemeMode::Dark => colors.background.blend(colors.input.opacity(0.30)),
        };
        let base = input_text_layout(div(), text_scale)
            .w_full()
            .min_w_0()
            .h(spacing * 8_f32)
            .px(spacing * 2.5_f32)
            .rounded(theme.radius.lg)
            .border_1()
            .border_color(border)
            .bg(if disabled {
                colors.input.opacity(if theme.mode == ThemeMode::Dark {
                    0.8
                } else {
                    0.5
                })
            } else {
                background
            })
            .font_family(theme.fonts.body)
            .text_color(colors.foreground)
            .text_size(px(14.) * text_scale)
            .focus_visible(move |style| {
                style
                    .border_color(if style_state.invalid {
                        border
                    } else {
                        colors.ring
                    })
                    .shadow(focus_ring.clone())
            })
            .when(disabled, |base| base.cursor_not_allowed());
        let value = style_state.value.clone();
        let base = if self.composite.is_some() {
            input_text_layout(div(), text_scale)
        } else {
            base
        };
        let base = if let Some(style) = self.style_with_state {
            style(style_state, base)
        } else {
            base
        };
        let placeholder = self.placeholder.unwrap_or_default();
        super::theme::apply_style(base, &self.style)
            .id(self.id.clone())
            .accessibility_id(self.id.to_string())
            .role(
                self.composite
                    .as_ref()
                    .and_then(|props| props.role)
                    .unwrap_or(Role::TextInput),
            )
            .aria_value(value)
            .aria_placeholder(placeholder.clone())
            .when_some(aria_label, |base, label| base.aria_label(label))
            .track_focus(
                &focus
                    .tab_stop(
                        self.composite
                            .as_ref()
                            .and_then(|props| props.tab_stop)
                            .unwrap_or(!disabled),
                    )
                    .tab_index(if disabled { -1 } else { 0 }),
            )
            .key_context("Input gpuicn-input")
            .focusable()
            .on_action(window.listener_for(&state, Editing::left))
            .on_action(window.listener_for(&state, Editing::right))
            .on_action(window.listener_for(&state, Editing::select_left))
            .on_action(window.listener_for(&state, Editing::select_right))
            .on_action(window.listener_for(&state, Editing::select_all))
            .on_action(window.listener_for(&state, Editing::home))
            .on_action(window.listener_for(&state, Editing::end))
            .on_action(window.listener_for(&state, Editing::word_left))
            .on_action(window.listener_for(&state, Editing::word_right))
            .on_action(window.listener_for(&state, Editing::select_word_left))
            .on_action(window.listener_for(&state, Editing::select_word_right))
            .on_action(window.listener_for(&state, Editing::select_home))
            .on_action(window.listener_for(&state, Editing::select_end))
            .on_action(window.listener_for(&state, Editing::copy))
            .on_action(window.listener_for(&state, Editing::enter))
            .on_action(window.listener_for(&state, Editing::undo))
            .on_action(window.listener_for(&state, Editing::redo))
            .on_action(window.listener_for(&state, Editing::backspace))
            .on_action(window.listener_for(&state, Editing::delete))
            .on_action(window.listener_for(&state, Editing::delete_word_left))
            .on_action(window.listener_for(&state, Editing::delete_word_right))
            .on_action(window.listener_for(&state, Editing::delete_to_start))
            .on_action(window.listener_for(&state, Editing::delete_to_end))
            .on_action(window.listener_for(&state, Editing::paste))
            .on_action(window.listener_for(&state, Editing::cut))
            .when(!disabled, |base| {
                base.on_mouse_down(
                    MouseButton::Left,
                    window.listener_for(&state, Editing::on_mouse_down),
                )
                .on_mouse_up(
                    MouseButton::Left,
                    window.listener_for(&state, Editing::on_mouse_up),
                )
                .on_mouse_up_out(
                    MouseButton::Left,
                    window.listener_for(&state, Editing::on_mouse_up),
                )
                .on_mouse_move(window.listener_for(&state, Editing::on_mouse_move))
            })
            .child(InputTextElement::new(state, placeholder))
    }
}

fn init(cx: &mut App) {
    if cx.has_global::<Initialized>() {
        return;
    }
    cx.set_global(Initialized);
    let context = Some("gpuicn-input");
    let command = if cfg!(any(target_os = "macos", target_family = "wasm")) {
        "cmd"
    } else {
        "ctrl"
    };
    let word = if cfg!(any(target_os = "macos", target_family = "wasm")) {
        "alt"
    } else {
        "ctrl"
    };
    #[cfg(target_family = "wasm")]
    cx.bind_keys([
        KeyBinding::new("ctrl-z", InputUndo, context),
        KeyBinding::new("ctrl-shift-z", InputRedo, context),
        KeyBinding::new("ctrl-left", InputWordLeft, context),
        KeyBinding::new("ctrl-right", InputWordRight, context),
        KeyBinding::new("ctrl-shift-left", InputSelectWordLeft, context),
        KeyBinding::new("ctrl-shift-right", InputSelectWordRight, context),
        KeyBinding::new("ctrl-backspace", InputDeleteWordLeft, context),
        KeyBinding::new("ctrl-delete", InputDeleteWordRight, context),
    ]);
    cx.bind_keys([
        KeyBinding::new(&format!("{command}-z"), InputUndo, context),
        KeyBinding::new(&format!("{command}-shift-z"), InputRedo, context),
        KeyBinding::new(&format!("{word}-left"), InputWordLeft, context),
        KeyBinding::new(&format!("{word}-right"), InputWordRight, context),
        KeyBinding::new(&format!("{word}-shift-left"), InputSelectWordLeft, context),
        KeyBinding::new(
            &format!("{word}-shift-right"),
            InputSelectWordRight,
            context,
        ),
        KeyBinding::new(&format!("{word}-backspace"), InputDeleteWordLeft, context),
        KeyBinding::new(&format!("{word}-delete"), InputDeleteWordRight, context),
        KeyBinding::new("shift-home", InputSelectHome, context),
        KeyBinding::new("shift-end", InputSelectEnd, context),
        #[cfg(any(target_os = "macos", target_family = "wasm"))]
        KeyBinding::new("cmd-shift-left", InputSelectHome, context),
        #[cfg(any(target_os = "macos", target_family = "wasm"))]
        KeyBinding::new("cmd-shift-right", InputSelectEnd, context),
        #[cfg(any(target_os = "macos", target_family = "wasm"))]
        KeyBinding::new("cmd-backspace", InputDeleteToStart, context),
        #[cfg(any(target_os = "macos", target_family = "wasm"))]
        KeyBinding::new("cmd-delete", InputDeleteToEnd, context),
        #[cfg(not(target_os = "macos"))]
        KeyBinding::new("ctrl-y", InputRedo, context),
    ]);
}

